using namespace std;

class Solution {
    bool is_square(long long x) {
        if (x < 0) return false;
        long long r = round(sqrt(x));
        return r * r == x;
    }
public:
    vector<long long> sumOfPerfectSquareAncestors(int n, vector<vector<int>>& edges, vector<int>& vals) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<long long> res(n, 0);
        auto dfs = [&](auto& self, int u, int p, long long cur_sum) -> void {
            res[u] = cur_sum;
            long long next_sum = cur_sum + (is_square(vals[u]) ? vals[u] : 0);
            for (int v : adj[u]) {
                if (v != p) {
                    self(self, v, u, next_sum);
                }
            }
        };
        dfs(dfs, 0, -1, 0);
        return res;
    }
};

import java.util.*;

class Solution {
    private boolean isSquare(long x) {
        if (x < 0) return false;
        long r = (long)Math.sqrt(x);
        return r * r == x;
    }

    public long[] sumOfPerfectSquareAncestors(int n, int[][] edges, int[] vals) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        long[] res = new long[n];
        dfs(0, -1, 0, adj, vals, res);
        return res;
    }

    private void dfs(int u, int p, long curSum, List<List<Integer>> adj, int[] vals, long[] res) {
        res[u] = curSum;
        long nextSum = curSum + (isSquare(vals[u]) ? vals[u] : 0);
        for (int v : adj.get(u)) {
            if (v != p) {
                dfs(v, u, nextSum, adj, vals, res);
            }
        }
    }
}

var sumOfPerfectSquareAncestors = function(n, edges, vals) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    function isSquare(x) {
        if (x < 0) return false;
        const r = Math.floor(Math.sqrt(x));
        return r * r === x;
    }
    const res = new Array(n).fill(0);
    function dfs(u, p, curSum) {
        res[u] = curSum;
        const nextSum = curSum + (isSquare(vals[u]) ? vals[u] : 0);
        for (const v of adj[u]) {
            if (v !== p) {
                dfs(v, u, nextSum);
            }
        }
    }
    dfs(0, -1, 0);
    return res;
};
